const errors = [];

if ($json.route !== 'command.new') {
  errors.push('Invalid route: expected command.new.');
}
if ($json.status !== 'ready') {
  errors.push('Invalid status: expected ready.');
}
if (!$json.payload || typeof $json.payload !== 'object' || Array.isArray($json.payload)) {
  errors.push('Invalid payload: expected an object.');
} else if ($json.payload.command !== 'new') {
  errors.push('Invalid payload command: expected new.');
}

return [{
  json: {
    ...$json,
    route_valid: errors.length === 0,
    route_error: errors.join(' '),
  },
}];

const payload = $json.payload && typeof $json.payload === 'object' && !Array.isArray($json.payload)
  ? $json.payload
  : {};
const commandArgs = Array.isArray(payload.command_args) ? payload.command_args : [];
const argumentText = typeof payload.argument_text === 'string' ? payload.argument_text.trim() : '';

let novelTitleRaw = '';
let novelGenreRaw = '';

if (commandArgs.length > 0) {
  novelTitleRaw = commandArgs[0] == null ? '' : String(commandArgs[0]);
  novelGenreRaw = commandArgs.length > 1 && commandArgs[1] != null ? String(commandArgs[1]) : '';
} else if (argumentText) {
  novelTitleRaw = argumentText;
}

return [{
  json: {
    ...$json,
    novel_title_raw: novelTitleRaw,
    novel_genre_raw: novelGenreRaw,
  },
}];

const normalizeSpaces = (value) => String(value ?? '').trim().replace(/\s+/gu, ' ');
const quotePairs = new Map([
  ['\"', '\"'],
  ["'", "'"],
  ['“', '”'],
  ['‘', '’'],
  ['「', '」'],
  ['『', '』'],
]);

let novelTitle = normalizeSpaces($json.novel_title_raw);
const closingQuote = quotePairs.get(novelTitle[0]);
if (closingQuote && novelTitle.length >= 2 && novelTitle.endsWith(closingQuote)) {
  novelTitle = normalizeSpaces(novelTitle.slice(1, -closingQuote.length));
}

return [{
  json: {
    ...$json,
    novel_title: novelTitle,
    novel_genre: normalizeSpaces($json.novel_genre_raw),
  },
}];

const validationErrors = [];
const titleLength = Array.from($json.novel_title ?? '').length;
const genreLength = Array.from($json.novel_genre ?? '').length;

if ($json.route_valid !== true) {
  validationErrors.push($json.route_error || 'Invalid route input.');
}
if (titleLength < 1) {
  validationErrors.push('Novel title is required.');
} else if (titleLength > 120) {
  validationErrors.push('Novel title must not exceed 120 characters.');
}
if (genreLength > 40) {
  validationErrors.push('Novel genre must not exceed 40 characters.');
}

return [{
  json: {
    ...$json,
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
  },
}];
